/* Ceremonial counties of England. North is at the top. Longitude is tightened so the shape is not stretched. */
export const mapFrame = {
  minLon: -6.366778174509677,
  maxLon: 1.768413197737257,
  minLat: 49.88223688287173,
  maxLat: 55.8116598312332,
  width: 560,
  height: 680,
  cos: 0.6039462326346925,
  scale: 107.46520519657157,
  offX: 16.0,
  offY: 21.396673078537106,
} as const;

export function project(lon: number, lat: number) {
  const f = mapFrame;
  return {
    x: f.offX + (lon - f.minLon) * f.cos * f.scale,
    y: f.offY + (f.maxLat - lat) * f.scale,
  };
}

